window.managementIdHash = function idHash(text) {
  let hash = 2166136261;
  for (const character of text) {
    hash ^= character.codePointAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
};

// 既存の裁定補正を適用した後に、公開用の管理IDを割り当てる。
window.assignStandardManagementIds = function (items, generatedEntries, previousIds, normalizeId) {
  const { cards, qa, generated } = window.STANDARD_MANAGEMENT_IDS;
  const reserved = new Set([
    ...Object.values(cards),
    ...Object.values(qa),
    ...Object.values(generated).flatMap(records => Object.values(records).map(([, id]) => id))
  ].map(normalizeId));
  const unavailable = new Set(reserved);
  const claimed = new Set();
  for (const item of items) {
    unavailable.add(normalizeId(item.overviewManagementId));
    for (const entry of item.qa || []) {
      unavailable.add(normalizeId(entry.managementId));
      for (const alias of entry.managementIdAliases || []) unavailable.add(normalizeId(alias));
    }
  }

  function assign(record, property, preset, seed) {
    const oldId = record[property];
    const isQa = property === "managementId";
    let id = preset;
    if (!id && isQa && /^R-[A-Z0-9]{8}$/.test(oldId) && !reserved.has(normalizeId(oldId))) id = oldId;
    if (!id || claimed.has(normalizeId(id))) {
      const range = isQa ? 36 ** 8 : 90000;
      let value = parseInt(window.managementIdHash(seed), 36) % range;
      do {
        id = isQa ? "R-" + value.toString(36).toUpperCase().padStart(8, "0") : String(10000 + value);
        value = (value + 1) % range;
      } while (unavailable.has(normalizeId(id)));
    }
    previousIds.set(record, oldId);
    unavailable.add(normalizeId(id));
    claimed.add(normalizeId(id));
    record[property] = id;
  }

  for (const item of items) {
    assign(item, "overviewManagementId", cards[item.name], item.name);
    const entries = item.qa || [];
    const formerRows = generated[item.name] || {};
    const byLegacyId = new Map(Object.values(formerRows));
    // QAが並べ替えられても未設定時の旧IDが別の質問に移らないよう、質問が一致するものを先に確保する。
    const byQuestion = entry => formerRows[window.managementIdHash(entry.question || "")]?.[1];
    const questionMatches = new Set(entries.map(byQuestion).filter(Boolean));
    for (const entry of entries) {
      const oldId = entry.managementId;
      const positionMatch = byLegacyId.get(oldId);
      let preset = byQuestion(entry);
      if (!generatedEntries.has(entry)) preset = qa[oldId] || preset;
      if (!preset && positionMatch && !questionMatches.has(positionMatch)) preset = positionMatch;
      assign(entry, "managementId", preset, item.name + "\n" + (entry.question || ""));
    }
  }
};
